import React from 'react';
import { graphql } from 'gatsby';
import { useTranslation } from 'gatsby-plugin-react-i18next';
import styled from 'styled-components';
import Layout from '../components/layout/Layout';

const GamesHero = styled.section`
  min-height: 40vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: ${props => props.theme.space[20]} ${props => props.theme.space[6]};
  background: linear-gradient(
    135deg,
    var(--color-bg) 0%,
    var(--color-surface) 100%
  );
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(
      circle at 50% 50%,
      rgba(0, 78, 137, 0.15) 0%,
      transparent 60%
    );
    pointer-events: none;
  }
`;

const HeroContent = styled.div`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  position: relative;
  z-index: 1;
  text-align: center;
`;

const Title = styled.h1`
  font-size: ${props => props.theme.typography.fontSizes['6xl']};
  margin-bottom: ${props => props.theme.space[4]};
  background: linear-gradient(
    135deg,
    ${props => props.theme.colors.secondary} 0%,
    ${props => props.theme.colors.primary} 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    font-size: ${props => props.theme.typography.fontSizes['4xl']};
  }
`;

const Subtitle = styled.p`
  font-size: ${props => props.theme.typography.fontSizes.xl};
  color: var(--color-text-secondary);
  max-width: 700px;
  margin: 0 auto;
  line-height: ${props => props.theme.typography.lineHeights.relaxed};
`;

const GamesSection = styled.section`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  padding: ${props => props.theme.space[16]} ${props => props.theme.space[6]};
`;

const GameCard = styled.div`
  display: flex;
  gap: ${props => props.theme.space[6]};
  margin-bottom: ${props => props.theme.space[8]};
  padding: ${props => props.theme.space[6]};
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: ${props => props.theme.radii.xl};
  transition: all 0.3s ease;

  &:hover {
    transform: translateY(-4px);
    border-color: ${props => props.theme.colors.primary};
  }

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    flex-direction: column;
  }
`;

const PreviewLink = styled.a`
  flex-shrink: 0;
  display: block;
  line-height: 0;
`;

const PreviewImage = styled.img`
  width: 200px;
  height: 200px;
  object-fit: cover;
  border-radius: ${props => props.theme.radii.lg};
  image-rendering: pixelated;

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    width: 100%;
    height: 220px;
  }
`;

const GameContent = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: ${props => props.theme.space[3]};
`;

const GameTitle = styled.h3`
  font-size: ${props => props.theme.typography.fontSizes['2xl']};
  color: var(--color-text);
  margin: 0;
  line-height: ${props => props.theme.typography.lineHeights.snug};
`;

const Tagline = styled.p`
  font-size: ${props => props.theme.typography.fontSizes.base};
  color: ${props => props.theme.colors.primary};
  font-style: italic;
  margin: 0;
`;

const Description = styled.p`
  font-size: ${props => props.theme.typography.fontSizes.base};
  color: var(--color-text-secondary);
  line-height: ${props => props.theme.typography.lineHeights.relaxed};
  margin: 0;
`;

const Meta = styled.p`
  font-size: ${props => props.theme.typography.fontSizes.sm};
  color: var(--color-text-secondary);
  margin: 0;
`;

const GameLinks = styled.div`
  display: flex;
  gap: ${props => props.theme.space[4]};
  flex-wrap: wrap;
  margin-top: ${props => props.theme.space[2]};
`;

const GameLink = styled.a`
  padding: ${props => props.theme.space[2]} ${props => props.theme.space[4]};
  background: rgba(255, 107, 53, 0.1);
  border: 1px solid ${props => props.theme.colors.primary};
  border-radius: ${props => props.theme.radii.md};
  font-size: ${props => props.theme.typography.fontSizes.sm};
  color: ${props => props.theme.colors.primary};
  text-decoration: none;
  transition: all 0.3s ease;

  &:hover {
    background: ${props => props.theme.colors.primary};
    color: white;
  }

  &.primary {
    background: ${props => props.theme.colors.primary};
    color: white;
    font-weight: ${props => props.theme.typography.fontWeights.semibold};
  }

  &.primary:hover {
    filter: brightness(1.08);
  }
`;

function GamesPage() {
  const { t } = useTranslation();

  const games = [
    {
      key: 'workreach',
      url: '/games/workreach/',
      preview: '/assets/images/publication_preview/workreach_game.jpg',
      paper: {
        cite: 'Langle-Chimal, Knoblauch & González, Nature Communications (2026)',
        url: 'https://www.nature.com/articles/s41467-026-78293-3'
      }
    }
  ];

  return (
    <Layout
      title={t('games.title', 'Games')}
      description={t('games.subtitle', 'Serious games built from my research.')}
      path="/games"
    >
      <GamesHero>
        <HeroContent>
          <Title>{t('games.title', 'Games')}</Title>
          <Subtitle>{t('games.subtitle', 'Serious games built from my research.')}</Subtitle>
        </HeroContent>
      </GamesHero>

      <GamesSection>
        {games.map(game => (
          <GameCard key={game.key}>
            <PreviewLink href={game.url} aria-hidden="true" tabIndex={-1}>
              <PreviewImage src={game.preview} alt="" />
            </PreviewLink>
            <GameContent>
              <GameTitle>{t(`games.${game.key}.title`)}</GameTitle>
              <Tagline>{t(`games.${game.key}.tagline`)}</Tagline>
              <Description>{t(`games.${game.key}.description`)}</Description>
              <Meta>
                {t(`games.${game.key}.meta`)}
                {game.paper && <> · {t('games.basedOn', 'Based on')} {game.paper.cite}</>}
              </Meta>
              <GameLinks>
                <GameLink className="primary" href={game.url}>
                  ▶ {t('games.play', 'Play')}
                </GameLink>
                {game.paper && (
                  <GameLink href={game.paper.url} target="_blank" rel="noopener noreferrer">
                    {t('games.paper', 'Read the paper')}
                  </GameLink>
                )}
              </GameLinks>
            </GameContent>
          </GameCard>
        ))}
      </GamesSection>
    </Layout>
  );
}

export default GamesPage;

export const query = graphql`
  query GamesPageQuery($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
